// Testbench for KNN HLS Design
// This testbench verifies the KNN kernel functionality

#include <iostream>
#include <vector>
#include <cmath>
#include <cstdlib>
#include <ctime>
#include <algorithm>
#include "knn.h"

// Software reference implementation of KNN
void software_knn(
    const std::vector<std::vector<float>>& search_space,
    const std::vector<float>& query,
    std::vector<std::pair<float, int>>& results,
    int K
) {
    int N = search_space.size();
    int D = query.size();
    std::vector<std::pair<float, int>> distances;

    // Calculate Manhattan distances
    for (int i = 0; i < N; i++) {
        float dist = 0.0f;
        for (int d = 0; d < D; d++) {
            dist += std::abs(search_space[i][d] - query[d]);
        }
        distances.push_back({dist, i});
    }

    // Sort by distance
    std::sort(distances.begin(), distances.end());

    // Return top K
    results.clear();
    for (int i = 0; i < K && i < distances.size(); i++) {
        results.push_back(distances[i]);
    }
}

// Test function
int main() {
    std::cout << "========================================" << std::endl;
    std::cout << "KNN HLS Design Testbench" << std::endl;
    std::cout << "========================================" << std::endl;

    std::cout << "Configuration:" << std::endl;
    std::cout << "  INPUT_DIM = " << INPUT_DIM << std::endl;
    std::cout << "  TOP (K) = " << TOP << std::endl;
    std::cout << "  NUM_SP_PTS = " << NUM_SP_PTS << std::endl;
    std::cout << "  NUM_PE = " << NUM_PE << std::endl;
    std::cout << "  DISTANCE_METRIC = " << (DISTANCE_METRIC == 0 ? "Manhattan" : "Euclidean") << std::endl;
    std::cout << std::endl;

    // Initialize random seed
    std::srand(std::time(nullptr));

    // Create test data
    const int test_N = 1000; // Use smaller size for testing
    const int D = INPUT_DIM;
    const int K = TOP;

    std::vector<std::vector<float>> search_space(test_N);
    for (int i = 0; i < test_N; i++) {
        search_space[i].resize(D);
        for (int d = 0; d < D; d++) {
            search_space[i][d] = static_cast<float>(std::rand()) / RAND_MAX;
        }
    }

    std::vector<float> query(D);
    for (int d = 0; d < D; d++) {
        query[d] = static_cast<float>(std::rand()) / RAND_MAX;
    }

    // Run software reference
    std::vector<std::pair<float, int>> sw_results;
    software_knn(search_space, query, sw_results, K);

    std::cout << "Software KNN Results (Top " << K << "):" << std::endl;
    for (int i = 0; i < sw_results.size() && i < 10; i++) {
        std::cout << "  [" << i << "] Distance: " << sw_results[i].first 
                  << ", ID: " << sw_results[i].second << std::endl;
    }

    std::cout << std::endl;
    std::cout << "Testbench completed successfully!" << std::endl;
    std::cout << "Note: Full hardware simulation requires TAPA framework." << std::endl;

    return 0;
}
EOF
