#ifndef __TAPA_H__
#define __TAPA_H__

#include <queue>
#include <vector>
#include <string>

namespace tapa {

// Mock mmap class
template<typename T>
class mmap {
public:
    T* data;
    size_t size;

    mmap() : data(nullptr), size(0) {}
    mmap(T* d, size_t s) : data(d), size(s) {}

    T& operator[](size_t idx) { return data[idx]; }
};

// Mock async_mmap class
template<typename T>
class async_mmap {
public:
    struct read_addr_stream {
        bool try_write(size_t addr) { return true; }
    } read_addr;

    struct read_data_stream {
        bool empty() { return true; }
        T read(void* nullp) { return T(); }
    } read_data;

    struct write_addr_stream {
        bool try_write(size_t addr) { return true; }
    } write_addr;

    struct write_data_stream {
        bool try_write(const T& data) { return true; }
    } write_data;

    struct write_resp_stream {
        bool empty() { return true; }
        int read(void* nullp) { return 0; }
