    ap_int operator^(const ap_int& other) const { return ap_int(val ^ other.val); }
    ap_int operator<<(int shift) const { return ap_int(val << shift); }
    ap_int operator>>(int shift) const { return ap_int(val >> shift); }

    ap_int& operator+=(const ap_int& other) { val += other.val; return *this; }
    ap_int& operator-=(const ap_int& other) { val -= other.val; return *this; }
