public:
    ap_uint<W>& parent;
    int hi, lo;

    ap_uint_range_ref(ap_uint<W>& p, int h, int l) : parent(p), hi(h), lo(l) {}

    // Copy from any range ref
    template<int SW>
    ap_uint_range_ref& operator=(const ap_uint_range_ref<SW>& value) {
        uint64_t v = value.parent.val;
        v = (v >> value.lo) & ((1ULL << (value.hi - value.lo + 1)) - 1);
        uint64_t mask = (1ULL << (hi - lo + 1)) - 1;
        parent.val = (parent.val & ~(mask << lo)) | ((v & mask) << lo);
        return *this;
    }

    // Assignment from ap_uint
    template<int SW>
    ap_uint_range_ref& operator=(const ap_uint<SW>& value) {
        uint64_t mask = (1ULL << (hi - lo + 1)) - 1;
